// ===================== Novedades: lo que cambió en cada versión, con fecha y cómo se usa =====================
// v: número interno (la versión se muestra como v0.0NN). d: fecha y hora (Argentina).
// items: [etiqueta, título corto, explicación, pasos para usarlo (opcional)]
const NEWS_TAGS = { sider: '🧩 Sider', interfaz: '🎨 Interfaz', kits: '👕 Kits', archivo: '📁 Archivo', plantel: '📋 Plantel', musica: '🎵 Música', velocidad: '⚡ Velocidad' };
const newsVer = v => 'v0.' + String(v).padStart(3, '0');
const NEWS = [
  { v: 52, d: '2026-10-14 23:30', t: "Minifaces al juego y escudos mejorados", lead: "Ahora podés poner la cara de cualquier jugador en el juego: subís una foto, la IA le saca el fondo y el editor la guarda como miniface. Y el creador de escudos suma 2K, vista previa y versiones para fondos oscuros y claros.", items: [
    ["plantel", "Minifaces al juego", "En la ficha de cada jugador hay una pestaña 🙂 Miniface: subís una foto PNG o JPG y el editor arma la miniface del juego (.dds DXT3 con transparencia y el ID del jugador). El fondo se quita con IA en un clic (la primera vez baja el modelo de internet), por color o tocando con la varita. La guía de la cabeza ayuda a encuadrar y el tamaño recomendado es 2048×2048.", ["Abrí un jugador y tocá la pestaña 🙂 Miniface.", "Elegí o soltá la foto y acomodala con el zoom y la guía.", "Tocá Guardar en el juego y abrí el juego de nuevo."]],
    ["sider", "La miniface va donde Sider la lee", "Se guarda en livecpk\\PESEditor-Minifaces y esa carpeta se agrega primera en sider.ini (con copia sider.ini.bak-pes-editor). Si el navegador no deja tocar sider.ini, la guarda en una carpeta que Sider ya lee. Borrar devuelve la miniface que había antes."],
    ["plantel", "Escudos en HD normal o 2K (experimental)", "El creador de escudos tiene Calidad: HD normal copia la medida de los escudos que ya hay en la carpeta, y 2K usa 512×520, 1028×1044 (_l) y 2056×2088 (_ll). 2K es experimental: en las pruebas el juego bajó 3 o 4 FPS y tuvo lag en algunos menús."],
    ["plantel", "Vista previa y versiones para fondos oscuros y claros", "Al cargar la imagen se ven los 11 archivos con su medida. Si el escudo tiene mucho negro, pregunta si r_b (fondos oscuros) aclara los negros con un fileteado claro; si tiene mucho blanco, si r_w (fondos claros) baja los blancos con un borde oscuro suave. En Dónde y cómo se guarda se explica qué significa cada letra."],
    ["plantel", "El escudo va a la carpeta correcta", "El escudo se guarda en la carpeta que Sider ya lee con escudos, y la carpeta PESEditor-Escudos ya no queda vacía cuando el navegador no deja tocar sider.ini."],
    ["archivo", "Las copias .bak-edit21 se borran solas", "Las copias de escudos, minifaces y kits sirven para deshacer mientras el editor está abierto. La próxima vez que lo abrís, con la carpeta Sider conectada, se borran. sider.ini.bak-pes-editor no se toca."],
    ["plantel", "Fotos de jugadores: más rápidas y pegando links", "La búsqueda usa el nombre completo de ESPN y Wikipedia en el idioma del jugador, así encuentra más jugadores. En Formación (vista Fotos) se puede pegar un link de SoFIFA, Sortitoutsi, PES Master, SoccerWiki o de cualquier imagen."],
    ["interfaz", "En desarrollo con barras de avance", "El cartel En desarrollo muestra cuánto falta de cada cosa con una barra de color y su porcentaje, marca las de prioridad alta y tiene un botón para ocultarlo."],
    ["interfaz", "Texto metálico en el modo PES 6", "En el modo gráfico PES 6 los textos de las tarjetas tienen un brillo metálico más marcado y se siguen leyendo bien."]
  ] },
  { v: 51, d: '2026-10-14 19:35', t: "La app de Windows ya se deja cerrar", lead: "Con cambios sin guardar, la X de la app para Windows no cerraba la ventana ni avisaba por qué. Ahora muestra un cuadro con tus opciones y después cierra.", items: [
    ["interfaz", "Salir del editor", "Si tocás la X de la app con cambios sin guardar, aparece el cuadro \"Salir del editor\": guardar en el caché (vuelven solos la próxima vez que abras ese EDIT), guardar en el juego, salir sin guardar o cancelar. Antes la ventana se quedaba abierta sin decir nada.", ["Hacé un cambio y tocá la X de la app.", "Elegí qué hacer con el cambio.", "La app se cierra."]],
    ["archivo", "Recargar, actualizar y cambiar de idioma", "En la app, F5 o Ctrl+R muestran el mismo cuadro para recargar. Cambiar de idioma guarda tus cambios en el caché y vuelven solos, y Actualizar sin guardar ya no se queda trabado."]
  ] },
  { v: 50, d: '2026-10-14 16:45', t: "¡Football Life 2026 es compatible!", lead: "El editor reconoce Football Life 2026: lee su base directo de los archivos del juego, muestra las valoraciones con su tope (104) y encuentra su EDIT. Además, un botón para buscar el EDIT a mano.", items: [
    ["archivo", "La base del juego, sin abrir el juego", "Al conectar la carpeta del juego, el editor lee la base directo de los data_s2526*.cpk de download, en el orden de spFileList.bin (gana la actualización más nueva), con las carpetas de Sider encima. 29.413 jugadores y 749 equipos, clásicos incluidos. Sirve también para PES 2021 (Data y download).", ["Tocá \"Conectar carpeta Sider\".", "Elegí la carpeta del juego (la que tiene FL_2026.exe) o una de más arriba.", "Listo: los nombres y las medias salen de la base del juego."]],
    ["plantel", "Valoraciones como las muestra cada juego", "PES 2021 llega a 109 y Football Life a 104: el editor se fija qué juego es por la carpeta del EDIT (…\\2026\\save en Football Life) o por el .exe conectado con Sider, y usa ese tope en las medias, la media rápida y el hexágono."],
    ["archivo", "Buscar EDIT", "Un botón al lado de Recargar lista los EDIT encontrados para pasar de uno a otro, busca de nuevo en Documentos, deja elegir la carpeta del EDIT o abrir el archivo a mano (se guarda como copia)."],
    ["sider", "Football Life en la pestaña Sider", "El chip ⚽ Football Life 2026 aparece con el Sider de SiderAddons. El módulo edit21_db funciona igual en ese juego."],
    ["musica", "Ventanita de música que se mueve", "La ventanita de Spotify y YouTube se arrastra desde \"⠿ mover\" y se agranda desde la esquina de abajo a la derecha; queda donde la dejes. Doble clic en \"mover\" la devuelve a su lugar."],
    ["interfaz", "En desarrollo se minimiza", "El cartel En desarrollo tiene un botón ▁ para dejarlo como una pestañita abajo a la derecha."]
  ] },
  { v: 47, d: '2026-10-14 16:00', t: "Kit Studio Pro: cargá kits desde un .zip (versión preliminar)", lead: "⚠️ Versión preliminar: todo esto es nuevo y se probó poco con juegos reales, así que es probable que tenga fallos; hacé una copia de content\\kit-server antes de cargar o reemplazar kits. El Estudio de kits ahora es el Kit Studio Pro, en dos partes (Uniformes y Editor), y un kit bajado de internet se carga arrastrando su .zip.", items: [
    ["kits", "Arrastrá el .zip y elegí el puesto", "Soltá el .zip del kit (o sus texturas sueltas: .ftex, .dds, .png) en Uniformes. Un cuadro muestra qué trae (kit, normal map, brillo, números, letras del nombre) y elegís el puesto: titular (p1), suplente (p2), tercera, cuarta o arquero. Lo que falte se genera genérico, todo se convierte a FTEX y se escriben solos el config.txt (con los colores leídos de la textura si no trae uno) y el order.ini.", ["Abrí el equipo, la pestaña Kit Studio Pro y quedate en Uniformes.", "Arrastrá el .zip a la zona punteada (o tocala para elegirlo).", "Elegí el puesto y tocá \"Cargar al kit-server\".", "Abrí el juego de nuevo (o en kserv apretá [0] para recargar el mapa)."]],
    ["kits", "Si el puesto ya tiene kit: reemplazar o agregar", "Si elegís un puesto en uso, el cuadro pregunta si reemplazar el kit de ahora (lo de antes se guarda en _borrados) o agregarlo como kit nuevo (p3, p4, g2…), y el orden se acomoda solo."],
    ["kits", "Los kits que viven en los .cpk", "Si el equipo no tiene carpeta en el kit-server, sus kits están cifrados dentro de los .cpk del juego y no se pueden abrir desde el editor. El Kit Studio Pro lo dice y deja cargarle un kit por Sider igual: crea la carpeta del equipo y su línea en map.txt."],
    ["kits", "Uniformes y Editor", "Uniformes muestra todos los kits del equipo con sus texturas en miniatura y el orden del juego; desde ahí se edita, se sube en el orden, se duplica (⧉), se copia un kit de jugador como arquero (🧤) y se borra (🗑, la carpeta queda en _borrados). Editor es un kit a pantalla ancha, con Ampliar, pantalla completa y Vista del juego."],
    ["kits", "Mové el nombre y los números sobre el modelo", "En el visor 3D, el nombre y los números de espalda, pecho y short se arrastran directo sobre la camiseta y la rueda encima les cambia el tamaño; los valores van al config.txt respetando el rango de cada kit. Las posiciones salen de una cuenta aproximada, todavía sin calibrar contra el juego: puede haber diferencias. Se apaga con \"✥ Mover nombre y números en el 3D\" en Prendas."],
    ["kits", "Texturas completas, color del short y textura que no se pierde", "Las texturas se cargan a su resolución completa (hasta 4096). El generador de fuentes tiene \"Número del short con otro color\". La textura subida a un kit ya no desaparece al cambiar de kit y volver."]
  ] },
  { v: 46, d: '2026-10-14 12:45', t: "La pestaña Sider entiende tu juego", lead: "La pestaña Sider ahora dice qué hace cada carpeta y cada módulo, se actualiza al instante al agregar o quitar, encuentra los módulos en subcarpetas y sugiere el nombre correcto si uno está mal escrito.", items: [
    ["sider", "Agregar, quitar y mover se ve al instante", "Al tocar \"＋\" en una carpeta de livecpk o en un módulo, aparece al final de su lista, resaltado, con un aviso, y el botón desaparece. Quitar, mover con las flechas, deshacer y aplicar el texto también se ven en el momento. Antes los cambios estaban, pero la lista no se actualizaba hasta volver a leer el archivo."],
    ["sider", "Qué hace cada carpeta y cada módulo", "Cada carpeta de contenido, cada módulo y cada carpeta de content tiene una línea que dice qué cambia en el juego. Hay más de 40 categorías (animaciones, banners de hinchadas, escenas, público, logos de manga, Liga Master, jugabilidad, cámaras…) y más de 60 módulos conocidos. Las cámaras se describen por el nombre: penaltyCam es la cámara de penales. Si un módulo no está en la lista, se usa lo que dice su propio archivo."],
    ["sider", "Mira adentro de cada carpeta", "Además de las rutas conocidas de PES 2021, busca nombres de carpeta que delatan el contenido hasta 7 niveles adentro: anime (poses del modo Editar y la previa), common_ad (banners de hinchadas), demo (escenas), scoreboard, turf y más. Funciona igual con PES 2021 base, con mods o con Football Life."],
    ["sider", "Módulos en subcarpetas y mods que viven en content", "Los módulos guardados en subcarpetas de modules (como modules\\GRAND\\Crowd-Server.lua) ya no aparecen como faltantes. Las carpetas de content se unen al módulo que las nombra en su código, y si ningún módulo las usa, lo dice."],
    ["sider", "¿Es FreeHeartEngine.lua? Corregir", "Si un lua.module está mal escrito (le falta una letra, tiene un guion en vez de un guion bajo…), la fila sugiere el archivo que sí está en modules y un botón lo corrige. Las comillas de más o de menos en una ruta ya no hacen que una carpeta aparezca como que no existe."],
    ["sider", "Carpetas repetidas, con sus filas", "El aviso de carpetas repetidas dice qué ruta se repite y en qué filas, y cada fila repetida lleva \"Repetida (fila N)\". Sider usa la primera; las otras se pueden apagar o quitar."]
  ] },
  { v: 45, d: '2026-10-14 06:30', t: "Pestaña Sider, música por link y cualquier Sider", lead: "La pestaña Sider muestra qué carga tu juego y deja ordenar sider.ini sin tocar el texto. La carga espera los escudos y revisa sider.ini, se puede conectar cualquier Sider y el EDIT sin Steam, y la música se suma pegando un link de YouTube o Spotify.", items: [
    ["sider", "Pestaña Sider: qué carga tu juego", "Al lado de WEPES hay una pestaña nueva, Sider. Lee tu sider.ini y muestra cada carpeta de contenido (cpk.root) con lo que trae adentro (escudos, fotos de jugadores, caras, kits, estadios, balones…) y qué herramienta del editor la usa, los módulos Lua que corre (kit server, caras, cantos, marcadores…) y las carpetas de content. También la versión de Sider, el ejecutable del juego y las carpetas de livecpk que no están en sider.ini.", ["Conectá tu carpeta Sider (si ya estaba conectada, no hace falta nada).", "Abrí la pestaña Sider."]],
    ["sider", "Prender, apagar, ordenar y agregar sin tocar el texto", "Cada carpeta y cada módulo tiene un interruptor (comenta la línea en sider.ini, no la borra, así se puede volver a prender), flechas para subir o bajar (el orden importa: si dos carpetas tienen el mismo archivo, manda la de más arriba) y una cruz para quitar la línea. Las carpetas de livecpk y los módulos que no están en sider.ini se agregan con un botón."],
    ["sider", "Ajustes de Sider explicados", "Los ajustes de sider.ini (livecpk, módulos Lua, cerrar Sider al salir, lado libre, barras negras, cámara, overlay, detalle del registro…) están como interruptores y listas, con una línea que dice para qué sirve cada uno. Si livecpk o los módulos están apagados, o una carpeta de cpk.root no existe, o falta un módulo en modules, aparece un aviso arriba."],
    ["sider", "Guardar con copia de seguridad", "Nada se escribe hasta tocar \"Guardar sider.ini\": antes, \"Cambios sin guardar\" y \"Deshacer los cambios\". La primera vez queda una copia en sider.ini.bak-pes-editor. Solo se reescriben las líneas que tocaste; los comentarios y el resto quedan igual, y el archivo se guarda con la misma codificación con la que estaba (UTF-8, UTF-16 o la del Bloc de notas con acentos). También podés ver y editar el texto completo."],
    ["sider", "La pantalla de carga revisa sider.ini", "Al entrar, después de \"Sider listo\", el editor lee sider.ini y dice cuántas carpetas de contenido y módulos tiene y de qué tipo. Si una carpeta no existe, falta un módulo o livecpk o los módulos están apagados, aparece un paso ⚠ con el detalle y, al terminar, un aviso con un botón a la pestaña Sider."],
    ["archivo", "Cualquier Sider: Football Life, la carpeta del juego o Steam", "Conectar Sider ya no exige un kit server en particular. Vale la carpeta de Sider (aunque todavía no tenga sider.ini, como Football Life, que lleva livecpk y modules en la carpeta del juego), la carpeta del juego o una de más arriba (Steam, steamapps): el editor busca unos niveles hacia abajo sin confundir el common de Steam con el de un cpk. Las caras y los escudos salen de las carpetas de sider.ini y del resto de livecpk."],
    ["archivo", "Si elegiste la carpeta equivocada, te dice cuál es", "Si la carpeta no sirve, el aviso dice qué parece ser (una carpeta de contenido, livecpk, content, el juego sin Sider, una carpeta vacía o una con tus cosas) y cuál tenés que elegir."],
    ["archivo", "El EDIT de la versión sin Steam", "El editor también encuentra el EDIT en <temporada>\\save, en cualquier subcarpeta de guardado y en carpetas tipo Football Life. Si no aparece, sigue unos niveles más abajo."],
    ["sider", "Si el navegador oculta sider.ini, elegilo a mano", "Chrome, Edge, Opera y Brave no dejan que las páginas vean los archivos .ini, .exe ni .dll, ni siquiera listándolos. Si al conectar tu carpeta Sider el editor dice que no encuentra sider.ini aunque esté, la pestaña Sider muestra qué ve en la carpeta y el botón \"📄 Elegir sider.ini a mano\": lo elegís una vez con el selector de archivos y el editor lo recuerda para leer y guardar. En la app para Windows esto no hace falta. Está en prueba: avisá si con tu juego no funciona.", ["Abrí la pestaña Sider y tocá \"📄 Elegir sider.ini a mano\".", "Elegí el sider.ini que está dentro de tu carpeta Sider."]],
    ["musica", "Agregar por link: YouTube y Spotify, sin cuentas", "En el reproductor, \"🔗 Agregar por link\" abre un solo cuadro: pegás el link de un video o una lista de YouTube, o de un tema, un disco o una lista de Spotify, y se suma a tu lista. Sin claves ni cuentas. Si escribís un nombre en vez de un link, se abre la búsqueda de YouTube o de Spotify en otra pestaña para que copies el link. Spotify completo necesita tu cuenta Premium iniciada; si no, suena un adelanto de 30 segundos.", ["Abrí el reproductor (abajo a la izquierda) y tocá \"🔗 Agregar por link\".", "Pegá el link: se agrega solo."]],
    ["musica", "Buscar en YouTube desde la app", "En PES Editor Rebuilt para Windows, si escribís un nombre en ese cuadro, la app busca en YouTube ahí mismo y tocás el resultado para sumarlo. Necesita el .exe nuevo de esta versión."],
    ["interfaz", "La carga espera los escudos y las fotos", "La pantalla de carga ahora espera a que estén los escudos conocidos, las caras del equipo abierto y las imágenes que se ven, así el editor aparece completo y no de a pedazos. La primera vez, si tarda, a los 6 segundos aparece \"Entrar ya\" (tope de 45 segundos)."],
    ["plantel", "Fotos de internet: segunda oportunidad", "Un pedido de foto o escudo rechazado por el sitio ya no queda guardado como \"sin foto\" para siempre: se vuelve a intentar."]] },
  { v: 44, d: '2026-10-13 20:15', t: "PES Editor Rebuilt llega a Windows como .exe", lead: "¡El editor ahora también es un programa para Windows! Descargás un .exe, lo abrís y conecta tu carpeta Sider aunque esté dentro de Archivos de programa, con permiso para guardar en el juego. Y estrenamos nombre: PES Editor Rebuilt.", items: [
    ["archivo", "PES Editor Rebuilt para Windows", "El editor ahora también se descarga como programa para Windows (.exe). Es exactamente el mismo editor de la página, en su propia ventana, con su logo y su acceso directo en el escritorio y en el menú Inicio. Hay un instalador y una versión portátil, que no se instala.", ["Abrí la release v0.044 en GitHub y descargá PES-Editor-Rebuilt-Setup.exe (o PES-Editor-Rebuilt-Portable.exe).", "Si aparece \"Windows protegió tu PC\", tocá Más información › Ejecutar de todas formas.", "Abrí PES Editor Rebuilt desde el escritorio o el menú Inicio."]],
    ["archivo", "Sider en Archivos de programa, con permiso para guardar", "Chrome y Edge no dejan que una página escriba en C:\\Program Files (x86), que es donde Steam instala PES 2021 y donde muchos tienen su carpeta Sider. La app sí puede: conecta tu carpeta Sider donde está, sin moverla, y guarda kits, escudos y el módulo edit21_db como siempre.", ["Abrí la app y elegí tu carpeta Documentos.", "Tocá Conectar carpeta Sider.", "Elegí tu carpeta Sider en el selector de Windows: queda conectada para la próxima."]],
    ["velocidad", "Siempre la última versión", "La app carga el editor desde GitHub cada vez que la abrís, así que cada versión nueva llega sola, sin reinstalar nada. Tiene su propio caché: guarda fotos, escudos, tus ajustes y el trabajo sin guardar, y después de la primera vez abre también sin internet."],
    ["archivo", "Solo las carpetas que elegís", "La app solo puede leer y escribir dentro de las carpetas que elegís con el selector de Windows (Documentos y tu carpeta Sider), y las recuerda para la próxima. Si Windows no deja escribir en alguna, te avisa que la abras como administrador; si el juego tiene un archivo abierto, te pide que lo cierres."],
    ["interfaz", "Nuevo nombre: PES Editor Rebuilt", "El editor pasa a llamarse PES Editor Rebuilt: en la pestaña del navegador, al instalarlo desde Chrome y en la app. La app estrena su propio logo."],
    ["archivo", "Qué hacer si Chrome no abre tu carpeta Sider", "Si Chrome dice \"Esta carpeta no se puede abrir… contiene archivos del sistema\", la pantalla de carga y la ayuda explican por qué pasa y te ofrecen descargar la app para Windows. También están los pasos para sacar solo la carpeta Sider de Archivos de programa (dentro del mismo disco tarda un segundo, aunque pese muchos GB) y la opción de abrirla solo para ver."],
    ["archivo", "sider.ini se arregla solo", "Si movés la carpeta Sider y tu sider.ini tenía rutas completas a la carpeta vieja (cpk.root = \"C:\\Program Files…\\livecpk\\…\"), al conectarla el editor las cambia por rutas relativas (.\\livecpk\\…) para que Sider las siga encontrando. Antes guarda una copia en sider.ini.bak-pes-editor."]
  ] },
  { v: 43, d: '2026-10-13 18:30', t: "Ficha hexagonal, media desde el plantel y tu trabajo a salvo", lead: "Cambiar la media de un jugador ahora es visual: un hexágono que se arrastra y una ventana que se abre desde el plantel. Y al actualizar el editor ya no perdés nada: te pregunta si guardar y tu trabajo queda en el caché.", items: [
    ["plantel", "Ficha hexagonal del jugador", "Arriba de la pestaña Habilidades hay un hexágono con seis áreas: Ataque, Técnica, Pase, Velocidad, Físico y Defensa. Cada punta es el promedio de las habilidades de esa área y se colorea según el valor. Los arqueros tienen su propio hexágono: Portero, Atajar, Despejar, Reflejos, Alcance y Físico.", ["Abrí un jugador de tu EDIT en la pestaña Jugadores.", "Entrá en Habilidades.", "Arrastrá una punta hacia afuera para subir esa área o hacia adentro para bajarla."]],
    ["plantel", "Mover un área sin desarmar al jugador", "Al mover una punta, todas las habilidades de esa área suben o bajan lo mismo, así se mantienen las diferencias entre ellas (un buen cabeceador sigue cabeceando mejor de lo que patea). Mientras arrastrás, la valoración aproximada se actualiza en vivo con el +/− que suma o resta. Cada movimiento es un solo paso de Deshacer."],
    ["plantel", "Cómo estaba antes", "Una línea punteada dentro del hexágono muestra cómo estaba el jugador al abrir el archivo, y al lado de cada área aparece cuánto cambió (+5, −3). Así ves de un vistazo qué tocaste."],
    ["plantel", "Hexágono también con el teclado", "Tocá una punta (o llegá con Tab) y usá las flechas: arriba o derecha suben 1, abajo o izquierda bajan 1, y RePág o AvPág mueven 5 de una."],
    ["plantel", "Hexágono de los jugadores del juego", "La ficha de un jugador que está en la base del juego pero no en tu EDIT también muestra su hexágono, solo para ver."],
    ["plantel", "Editar la media desde el plantel", "En la tabla del plantel, la valoración (columna Val.) de cada jugador ahora es un botón con un lápiz ✎. Al tocarlo se abre una ventana encima de la página con la media en grande, botones −5, −1, +1 y +5, una barra para elegirla entre 40 y 99 y el hexágono del jugador para ajustar cada área.", ["Abrí un equipo: aparece en Plantel.", "Tocá el número de la columna Val. de un jugador.", "Usá los botones, la barra o el hexágono.", "Tocá Listo (o Esc) y el plantel se actualiza."]],
    ["plantel", "Qué toca la media rápida", "En los jugadores de campo, cambiar la media sube o baja por igual todas las habilidades de juego; las de arquero no se tocan. En los arqueros se mueven las habilidades de arquero y el salto. El editor busca el cambio que deja la media lo más cerca posible de la que elegiste y, si las habilidades ya están en el tope (99) o en el piso (40), te avisa."],
    ["plantel", "Volver atrás sin miedo", "La ventana muestra cuánto cambió la media desde que la abriste. \"Volver a como estaba\" deshace todo lo de esa ventana (queda en Rehacer), Ctrl+Z y Ctrl+Y funcionan adentro y \"Abrir ficha completa\" te lleva a la pestaña Habilidades del jugador. Si el jugador es del juego y no está en tu EDIT, la ventana ofrece agregarlo para poder editarlo."],
    ["velocidad", "El aviso de versión nueva, más rápido y seguro", "Con la pestaña a la vista, el editor revisa cada 3 minutos si hay una versión nueva (antes cada 10), y también apenas volvés a la pestaña. Además mira el último cambio publicado en GitHub: cuando aparece uno, revisa cada 30 segundos hasta que la página nueva está lista. Las revisiones piden los archivos con una marca única, así ni el navegador ni GitHub pueden contestar con una copia vieja. El aviso muestra el título del cambio."],
    ["velocidad", "Actualizar trae todo de nuevo", "\"Actualizar ahora\" recarga la página pidiendo cada archivo otra vez a GitHub, así no queda ninguna parte de la versión anterior."],
    ["archivo", "Antes de recargar, te pregunta", "Si tocás \"Actualizar ahora\" o \"Borrar caché\" con cambios sin guardar, aparece un cuadro con tus opciones: Guardar en el caché y recargar, Guardar en el juego y recargar (o Guardar copia, si abriste el archivo a mano), Actualizar sin guardar o Cancelar. Si al guardar en el juego algo falla, no recarga."],
    ["archivo", "Tu trabajo, guardado en el caché", "Al recargar, el EDIT con tus cambios queda guardado en este navegador junto con el historial de Deshacer y la pantalla donde estabas. Cuando el editor vuelve a abrir ese mismo EDIT, todo vuelve solo y te avisa cuántos cambios recuperó. Funciona con la carpeta del juego y con un archivo abierto a mano, y lo guardado dura un día.", ["Hacé cambios en un jugador o un equipo.", "Cuando aparezca \"Hay una versión nueva del editor\", tocá Actualizar ahora.", "Elegí \"Guardar en el caché y recargar\".", "Al volver a cargar, seguís donde estabas, con Deshacer."]],
    ["archivo", "Si el juego guardó mientras tanto", "Si el juego modificó el EDIT entre que guardaste en el caché y volviste, el editor lo nota: sin cambios pendientes abre el del juego; con cambios pendientes los recupera y te ofrece recargar el del juego, y al guardar te vuelve a avisar antes de pisarlo."],
    ["interfaz", "Arreglo: \"cambios sin guardar\" a la vista", "En pantallas de 1366 px de ancho o menos, con la carpeta del juego abierta, el aviso \"N cambios sin guardar\" de la barra de pestañas quedaba escondido. Ahora siempre se ve; solo se esconde la etiqueta \"Modo copia\"."]] },
  { v: 42, d: '2026-10-13 15:45', t: 'Valoración dinámica con datos reales', lead: "La valoración por rendimiento ahora mira toda la temporada, los goleadores, las lesiones y el historial de cada jugador, y te muestra de dónde sale cada punto.", items: [
    ["plantel", "Búsqueda que encuentra a tu equipo", "\"Como 1907\" ahora encuentra a \"Como\": el editor prueba el nombre sin el año, sin siglas como FC, Club o Calcio y con la palabra más importante, y usa el país del equipo en tu EDIT para elegir bien."],
    ["plantel", "Toda la temporada, no solo 6 partidos", "Con ESPN, el editor analiza en segundo plano todos los partidos de la temporada: goleadores, asistencias, minutos y puntaje de cada jugador. También trae la campaña de la temporada anterior.", ["Abrí un equipo y entrá en Formación.", "Tocá \"⚽ Últimos partidos reales\" con la fuente ESPN.", "Dejá marcado \"Analizar toda la temporada\" y esperá a que termine."]],
    ["plantel", "Lesionados y ausentes", "El plantel de ESPN dice quién está lesionado o en duda. El lesionado baja su forma (más si lleva más de dos meses afuera), y también el habitual que faltó a las últimas 3 citaciones."],
    ["plantel", "Historial de cada jugador", "Las temporadas anteriores de cada jugador moderan la forma: una racha corta no lo vuelve crack, un mal mes no lo hunde y el titular de siempre suma."],
    ["plantel", "Cómo se calcula, jugador por jugador", "En Forma del plantel cada jugador tiene un botón ⓘ con el detalle: cada parte de la forma con sus números, la edad y los topes. La ayuda \"Cómo se calcula la forma\" explica la fórmula completa.", ["Abrí \"📊 Forma del plantel\".", "Tocá ⓘ al lado de un jugador."]],
    ["interfaz", "En desarrollo", "Un cartel muestra lo que está en prueba y lo que viene. También queda arriba de todo en Novedades."]] },
  { v: 41, d: '2026-10-13 14:45', t: 'Escudos propios y siempre la última versión', lead: 'Escudos propios en un par de clics, el editor que se actualiza solo y una salida para quienes tienen Sider dentro de Archivos de programa.', items: [
    ['plantel', 'Subí tus propios escudos', 'En Datos y colores hay una sección Escudo. Subís un PNG (o tus archivos e_XXXXXX_*.png) y el editor arma los 11 archivos que usa el juego, cada uno con su tamaño y con el ID de 6 cifras del equipo, y los guarda en livecpk\\…\\common\\render\\symbol\\flag. Lo que había queda como .bak-edit21.', ['Conectá la carpeta Sider.', 'Abrí un equipo y entrá en Datos y colores.', 'En Escudo tocá "Elegir imagen o archivos" (o arrastrá el PNG).', 'Tocá "Guardar escudo en el juego" y abrí el juego de nuevo.']],
    ['plantel', 'Carpeta de escudos automática', 'Si tu Sider no tiene ninguna carpeta con escudos, el editor crea livecpk\\PESEditor-Escudos y la agrega a sider.ini, antes de las otras, para que tus escudos manden. Guarda una copia del sider.ini como sider.ini.bak-pes-editor.'],
    ['archivo', 'Sider dentro de Archivos de programa', 'Chrome y Edge no dejan abrir para escribir carpetas dentro de C:\\Program Files, donde Steam instala el juego. Ahora la pantalla de carga lo explica y ofrece "Abrir solo para ver": se ven kits, caras, escudos y nombres. Para poder guardar en el juego, mové el juego a otra biblioteca de Steam.'],
    ['velocidad', 'Siempre la última versión', 'El editor revisa sus archivos contra GitHub cada vez que abre, así ya no queda una copia vieja después de una actualización. Si se publica algo nuevo con la página abierta, aparece arriba "Hay una versión nueva del editor" con Actualizar ahora o Más tarde.'],
    ['velocidad', 'Fotos y escudos guardados', 'Las fotos y escudos de internet se descargan una sola vez y después cargan al instante, también sin conexión.'],
    ['interfaz', 'Versión a la vista y Borrar caché', 'Debajo de la versión, arriba, se ve la fecha de la versión que estás usando. En Apariencia hay una sección Caché con la versión, cuántas fotos hay guardadas, el espacio usado y el botón Borrar caché, en los 4 modos gráficos.']] },
  { v: 40, d: '2026-10-13 11:15', t: 'Ahora en inglés, y una Formación más cómoda', lead: 'El editor aprende inglés, la Formación deja mover varios jugadores a la vez y muestra el valor de Transfermarkt, y cada modo gráfico gana animaciones propias.', items: [
    ['interfaz', 'El editor en inglés', 'Al lado de Recargar hay un selector con la bandera del idioma: Español o English. En inglés se traduce todo lo que se ve: pestañas, botones, ayudas, Novedades, la barra de PES 6, países y posiciones. También se elige en la pantalla de carga, junto a Música.', ['Tocá la bandera al lado de Recargar.', 'Elegí English: la página se recarga en inglés y queda guardado.']],
    ['plantel', 'Mover varios jugadores juntos', 'En Formación tocá jugadores con Ctrl apretado o usá "Elegir varios": quedan marcados y, al arrastrar uno, se mueven todos juntos. El arquero queda fijo y Deshacer vuelve todo atrás.'],
    ['plantel', 'Banco de suplentes más largo', 'Sin un jugador elegido, la lista de suplentes se alarga y se ven muchos más de una vez.'],
    ['plantel', 'Valor de Transfermarkt', 'La cabecera de Formación muestra el valor estimado y el de Transfermarkt, que cargás tocándolo. La ↗ abre la búsqueda del equipo en Transfermarkt y abajo dice cuánto difiere. En Retro es una caja de PS2 y en PES 6 una placa plateada con el número dorado.'],
    ['interfaz', 'Panel de equipos más ancho', 'Más ancho, con Ordenar al lado de Todos, Editados y Sin guardar, un selector de Liga o país que dice cuántos clubes tiene cada uno, y orden por País.'],
    ['plantel', 'Escudos de Wikipedia', 'Si TheSportsDB no tiene el escudo de un club, se busca en su página de Wikipedia. Los clubes que habían quedado sin escudo se buscan otra vez.'],
    ['interfaz', 'Pestañas con personalidad', 'La pestaña elegida tiene una animación propia en cada modo gráfico: brillo en Moderno, franja naranja en Clásico, flechita que titila en Retro y un trazado rojo que da vueltas en PES 6.'],
    ['interfaz', 'Estática de tele en PES 6', 'En PES 6 Editar, al cambiar de pestaña, equipo o sección aparece un golpe de estática, como al cambiar de canal. El eco del logo ahora sale de adentro hacia afuera.'],
    ['musica', 'El video se va de verdad', 'A los 15 segundos el cuadro de YouTube desaparece y queda la carátula chica del reproductor con un ▶. La ✕ del video lo saca para todos los temas que vengan, y la música sigue sonando.'],
    ['musica', 'Arreglo: el video no se escondía', 'El video de YouTube a veces no se escondía a los 15 segundos porque dependía de avisos de YouTube. Ahora se mide con el tiempo real del video, y cuando se esconde ya no queda el cuadro ocupando lugar.'],
    ['plantel', 'Arreglo: clubes sin escudo', 'Los clubes que TheSportsDB no encontraba quedaban sin escudo para siempre. Ahora se vuelven a buscar una vez, con Wikipedia como respaldo.']] },
  { v: 30, d: '2026-10-13 09:55', t: 'Lavada de cara: PES 6 Editar, plantel y carga', lead: 'Una versión dedicada a cómo se ve: el modo PES 6 Editar se pone nostálgico, el plantel muestra más cosas de un vistazo y la pantalla de carga te acompaña a conectar todo.', items: [
    ['interfaz', 'PES 6 Editar, como en la PS2', 'Fondo de estadio con un leve desenfoque y efecto de tele vieja (CRT), tabla del plantel en dorado suave, bordes rectos y el logo que respira con una segunda capa que lo acompaña.'],
    ['interfaz', 'La barra de texto de abajo', 'En PES 6 Editar corre despacio una cinta con novedades, ideas a futuro y datos de la saga, en letra blanca de PES. Al pasar el mouse por un botón o una pestaña, explica qué hace.'],
    ['interfaz', 'Toda la pantalla, en una fila', 'En la PC el editor ocupa todo el ancho, la cabecera entra en una sola fila y Apariencia tiene íconos y vistas previas de cada paleta. Las acciones de cada jugador están en el botón ⋯.'],
    ['plantel', 'Banderas reales y fotos más grandes', 'La columna Nación muestra la bandera de verdad del país. Las fotos son más grandes y su borde y fondo cambian según la posición: arquero, defensa, medio o delantero.', ['Abrí un equipo y entrá en Plantel.', 'Con "Fotos / Camisetas" elegís ver las caras o solo la camiseta del equipo.']],
    ['plantel', 'Promedios explicados', 'Debajo del plantel se aclara que media, edad y altura son promedios del plantel y que el valor es la suma de todos.'],
    ['plantel', 'El estadio real en la cabecera', 'Arriba de todo se ve el nombre real del estadio y, entre paréntesis, el que tiene elegido el EDIT.'],
    ['plantel', 'Fotos de dos lugares', 'Al cargar elegís: fotos recortadas de TheSportsDB, una mezcla que completa con fotos de Wikipedia las que falten, o ninguna. Se cambia después en Formación, con la vista Fotos.'],
    ['archivo', 'La carga te pide Sider', 'Después de abrir el EDIT, la pantalla de carga pide conectar la carpeta Sider (o el permiso para volver a leerla) y espera a que carguen caras, escudos y fuentes antes de entrar. El botón de nombres ahora se llama "Conectar Player.bin".'],
    ['musica', 'Carátula en lugar del video', 'El reproductor quieto queda como un círculo, y a los 15 segundos de empezar un video de YouTube queda solo la carátula. Tocándola vuelve el video.'],
    ['interfaz', 'Windows en modo oscuro', 'En PES 6 Editar y Clásico, con Windows en modo oscuro, el dorsal repetido y las casillas ya no quedan en negro.']] },
  { v: 20, d: '2026-10-13 08:25', t: 'El Plan de juego, como en el juego', lead: 'La pestaña Formación usa las mismas opciones y nombres que el Plan de juego de PES 2021, con su explicación, y suma el capitán y los lanzadores de balón parado. Todo verificado en el juego.', items: [
    ['plantel', 'Estrategia con los nombres del juego', 'Ataque en rosa y defensa en celeste; cada opción es una tarjeta con lo que hace. Las líneas defensiva, de apoyo y la distancia al jugador con balón traen la explicación del juego.'],
    ['plantel', 'Las 4 instrucciones avanzadas', '2 de ataque y 2 de defensa por plan, como en el juego, sin repetir la misma. 13 de 14 confirmadas en el juego; Delantero liberado figura como "probable" porque el juego la muestra como "No" si no tiene un delantero asignado.', ['Abrí un equipo y entrá en Formación.', 'En "Instrucciones avanzadas", tocá hasta 2 por lado. Tocá una marcada para quitarla.']],
    ['plantel', 'Opciones tácticas rápidas', 'Las del juego (Balones largos a la contra, Contraataques rápidos, Juego de posesión, Defensa total, Todos adelante, Por las bandas y Por el centro) cambian varias opciones de una vez. Los valores son aproximados porque el juego no los guarda en el EDIT.'],
    ['plantel', 'Config. marcaje', 'Avisa si algún jugador marca a un rival fijo y lo devuelve a automático con un toque.'],
    ['plantel', 'Capitán y balón parado', 'Capitán, tiro libre largo y corto, tirador 2, córner izquierdo y derecho, penales y los 3 jugadores ofensivos, igual que "Opciones del jugador" del juego. "Elegir automáticamente" elige un titular por jugada según sus habilidades.'],
    ['kits', 'Equipación para varios jugadores', 'Con varios seleccionados en Plantel, "Equipación…" cambia mangas, camiseta interior, medias, calzas, camiseta afuera, guantes, color de guantes y botines a todos a la vez.'],
    ['archivo', 'Revisión antes de guardar', 'El editor vuelve a abrir el EDIT generado y revisa cantidades e IDs de jugadores, equipos y planteles; si aparece un problema nuevo, no guarda y muestra la lista.'],
    ['archivo', 'Comparar con otro EDIT más claro', 'Nombra cada lanzador, cada instrucción avanzada y la Config. marcaje.'],
    ['interfaz', 'Adaptado a cada modo gráfico', 'La Estrategia cambia de look en Moderno, Clásico, Retro y PES 6 Editar.']] },
  { v: 19, d: '2026-10-13 06:55', t: 'Todos los jugadores del juego en Jugadores', lead: 'La pestaña Jugadores ya no muestra solo los que están en tu EDIT: con la base del juego copiada, se ven los más de 27.000 jugadores del juego.', items: [
    ['plantel', 'Mi EDIT o la base del juego', 'Arriba de la lista hay dos botones: "Mi EDIT" (los jugadores que el EDIT guarda y se editan como siempre) y "Del juego" (todos los de la base del juego). Si tu EDIT no tiene jugadores, arranca directo en la base. La pestaña muestra el total de la base, y al pasar el mouse dice cuántos hay en cada lado.', ['Conectá la carpeta Sider y dejá que el juego copie la base (si todavía no lo hiciste, el editor te avisa cómo).', 'Entrá en Jugadores y tocá "Del juego".', 'Buscá por nombre, ID o equipo, o filtrá por posición o por "Solo los que no están en mi EDIT".']],
    ['plantel', 'Ficha de solo lectura con todo lo del juego', 'Cada jugador de la base muestra su cara, posición, nacionalidad, edad, altura, valoración, sus equipos con el dorsal (tocá uno para ir al plantel) y todas las habilidades en barras, más pierna mala, estado de forma y resistencia a lesiones. Es lo que usa el juego.'],
    ['plantel', 'Agregar a mi EDIT para editarlo', 'El botón "Agregar a mi EDIT para editarlo" copia al jugador con todas sus habilidades y abre su ficha editable; la cara y el nombre siguen saliendo del juego. Ctrl+Z lo deshace.'],
    ['plantel', 'El buscador de arriba también encuentra jugadores de la base', 'Con / o el buscador de arriba aparecen los jugadores del juego que no están en ningún plantel de tu EDIT, marcados como "Base del juego"; al elegir uno se abre su ficha.']] },
  { v: 18, d: '2026-10-13 06:30', t: 'La copia de la base ya se guarda y el video va arriba del reproductor', lead: 'Arreglo del módulo edit21_db.lua (en algunas instalaciones Sider no deja que los módulos guarden archivos), planteles de la base verificados con los archivos reales del juego y un lugar mejor para el video de YouTube.', items: [
    ['archivo', 'Escritura con las funciones de Windows', 'En algunas instalaciones, el io de Sider no deja crear ni sobrescribir archivos: abrir un archivo para escribir devuelve vacío y sin error (en el sider.log se ve como "-> nil", y le pasa también a otros módulos, como PostProcessingEditor y UIColors). La v1.5 lo detecta y en ese caso escribe la copia con las funciones de Windows, por medio del ffi de LuaJIT que el juego ya deja activado (luajit.ext.enabled = 1 en sider.ini). En sider.log queda anotado qué método usó.', ['Tocá "Conectar carpeta Sider": el editor reemplaza el módulo viejo por la v1.5 (guarda el anterior como edit21_db.lua.anterior).', 'Abrí el juego hasta el menú principal, entrá en Partido › Amistoso hasta la elección de equipos y cerralo.', 'Volvé al editor y tocá "Ya lo hice: volver a leer".']],
    ['archivo', 'Nada de archivos al arrancar', 'El módulo ya no toca ningún archivo mientras Sider arranca: elige la carpeta recién cuando el juego carga el primer archivo de la base, la crea si no existe y, si algo falla, vuelve a probar con el siguiente.'],
    ['plantel', 'Planteles de la base verificados', 'Con la copia real de PlayerAssignment.bin se confirmó cómo guarda el juego cada fila (registro de 16 bytes: número de fila, jugador, equipo, dorsal y orden). El editor ahora lo reconoce directo, y el dorsal se calibra comparando con los planteles de tu EDIT: el juego lo guarda empezando desde 0, así que el 1 figura como 0. En la prueba con el juego coincidieron los 20.174 jugadores de los 748 equipos.'],
    ['musica', 'Video de YouTube arriba del reproductor', 'Con el reproductor minimizado, el video ahora va arriba de la barra, en el espacio libre de la izquierda, y toma el ancho que haya (mínimo 200 × 200, lo que exige YouTube). Si la pantalla es angosta y no hay hueco, sigue al costado del reproductor para no tapar la lista de equipos.'],
    ['archivo', 'Aviso más preciso', 'Si el sider.log muestra el error de una versión anterior del módulo, el aviso ya no manda a revisar la protección contra ransomware de Windows: explica qué pasó y que alcanza con repetir los pasos. Las líneas de ayuda que el módulo deja en el registro ya no se confunden con un error de permisos.']] },
  { v: 17, d: '2026-10-13 05:30', t: 'Módulo de Sider automático y más datos de la base', lead: 'Al conectar la carpeta Sider, el editor instala solo el módulo que copia la base del juego, y ahora lee más datos de esa copia.', items: [
    ['archivo', 'El módulo edit21_db.lua se instala solo', 'Al tocar "Conectar carpeta Sider", el editor revisa tu Sider: si falta el módulo lo copia a modules\\, agrega la línea lua.module = "edit21_db.lua" en sider.ini (guardando una copia de seguridad como sider.ini.bak-pes-editor) y crea la carpeta content\\edit21-db. Si ya está pero es una versión vieja, lo actualiza. Es un módulo de solo lectura: no cambia nada del juego.', ['Tocá "Conectar carpeta Sider" y elegí la carpeta de Sider (la que tiene sider.exe).', 'Si el editor te pide permiso para escribir en esa carpeta, aceptá: lo necesita para instalar el módulo.']],
    ['archivo', 'Aviso cuando la base no está cargada', 'Si es la primera vez, si el módulo se acaba de instalar o si en content\\edit21-db faltan archivos, el editor muestra qué hacer: abrir PES 2021 con Sider hasta el menú principal, entrar en Partido › Amistoso hasta la elección de equipos y cerrar el juego. Después, "Ya lo hice" vuelve a leer la base. También avisa al arrancar si la copia está incompleta.'],
    ['archivo', 'Módulo v1.3: copia toda la base y avisa si algo falla', 'Si Windows no le deja escribir en content\\edit21-db, el módulo prueba en content\\pes-editor-db, anota el error exacto en sider.log y deja un estado.txt; el editor lee ese registro y te dice qué pasó y cómo arreglarlo (por ejemplo, el "Acceso controlado a carpetas" de Windows). Además copia todos los archivos de pesdb que el juego carga (Player, Team, PlayerAssignment, Coach, Stadium, Country, Competition, Tactics…), no solo una lista fija, y escribe index.txt con el nombre, tamaño y hora de cada uno. Los archivos de la elección de equipos (como PlayerAssignment.bin) recién se copian al entrar en el amistoso: por eso ese paso.'],
    ['plantel', 'Planteles de la base para equipos vacíos', 'Con PlayerAssignment.bin y Team.bin copiados, el editor sabe qué jugadores tiene cada equipo en el juego y el nombre y la sigla de los 750 equipos. Si un equipo está vacío en tu EDIT, la pestaña Plantel muestra el plantel que trae el juego, con dorsales, fotos y valoraciones.', ['Abrí un equipo sin plantel (activá "Incluir sin plantel" en la lista).', 'Tocá un jugador para abrirlo; si no estaba en tu EDIT, el editor ofrece agregarlo con sus habilidades.', 'Con "Copiar este plantel a mi EDIT" se agregan todos de una vez (hasta 40). Se puede deshacer con Ctrl+Z.']],
    ['plantel', 'Datos más precisos de los jugadores', 'Los jugadores que están en la base pero no en tu EDIT se leen con todas sus habilidades, altura, edad, nacionalidad y posiciones desde la copia de Player.bin, así que las valoraciones y los valores se calculan igual que para los editados.']] },
  { v: 16, d: '2026-10-13 05:00', t: 'Código ordenado en archivos', lead: 'Limpieza interna: el editor pasó de un solo archivo gigante a archivos separados, sin cambiar ninguna función.', items: [
    ['archivo', 'HTML corto, CSS y JavaScript aparte', 'La página principal pasó de 17 MB a unos 6 KB: los estilos están en css/editor.css y el código en la carpeta js, un archivo por cada parte (plantel, formación, kits, 3D, reproductor, gráficos, etc.). En tu PC queda "Editor EDIT 21.html" junto a la carpeta "pes-editor-files", que tiene que estar al lado para que funcione.'],
    ['archivo', 'Código revisado', 'Se revisó que no haya funciones repetidas ni sin uso, y se quitó la que abría carpetas con los botones viejos. El ícono de la pestaña también pasó a ser un archivo.'],
    ['velocidad', 'Carga más liviana', 'Al estar separado, el navegador guarda cada archivo y en las próximas visitas solo baja lo que cambió. La app instalable guarda todos los archivos para funcionar sin internet.']] },
  { v: 15, d: '2026-10-13 04:45', t: 'YouTube: volumen fijo y video más chico', lead: 'Arreglos en los temas de YouTube del reproductor.', items: [
    ['musica', 'El volumen se mantiene al cambiar de tema', 'Al pasar de un video de YouTube a otro, el nuevo podía arrancar silenciado o con otro volumen: el navegador silenciaba el segundo reproductor porque no lo habías tocado. Ahora todos los videos suenan en un solo reproductor, con el volumen que elegiste. Entre dos videos el pase es: baja, cambia y sube.'],
    ['musica', 'Video más chico y al costado', 'El video ahora mide 200 × 200 (lo mínimo que permite YouTube) y está al lado del reproductor, no arriba, así no tapa la lista de equipos. Con el panel abierto sigue ocupando el lugar de la carátula.'],
    ['musica', 'En el celular, sin video encima de la página', 'En pantallas chicas el video de YouTube no aparece sobre la página: se ve solo con el reproductor abierto. Como YouTube no permite que su audio siga con el video oculto, al cerrar el panel ese tema se pausa y vuelve a sonar al abrirlo. Las canciones propias suenan siempre.']] },
  { v: 14, d: '2026-10-13 04:25', t: 'Una fuente para cada estilo e ícono nuevo', lead: 'Cada estilo gráfico trae su propia fuente, y la pestaña del navegador estrena ícono.', items: [
    ['interfaz', 'Fuente según el estilo', 'Moderno usa Outfit para el texto y Big Shoulders para los títulos: modernas y fáciles de leer. PES 6 Editar usa QuickExpress, la del estilo PES. Retro usa Pixelify Sans y Silkscreen, letras de píxeles inspiradas en los Winning Eleven de PlayStation 1 pero legibles. Clásico usa Tahoma, como los programas de escritorio de antes. Las fuentes nuevas vienen dentro de la página (licencia libre OFL), así que funcionan sin internet.'],
    ['interfaz', 'Cambiar la fuente en cualquier estilo', 'La fuente se elige por estilo: lo que cambies en Retro queda para Retro, y lo de Moderno para Moderno. QuickExpress sigue disponible en todos.', ['Elegí el estilo en "🖥️ Gráficos".', 'Tocá "🎨 Apariencia" y en "Fuente de la página" elegí otra, o "La del estilo" para volver a la de siempre.']],
    ['interfaz', 'Ícono nuevo en la pestaña del navegador', 'La pestaña del navegador muestra el logo PES con un borde oscuro, para que se vea tanto con el navegador en modo claro como en oscuro.']] },
  { v: 13, d: '2026-10-13 04:10', t: 'PES 6 más fiel, capitán en Acciones y pestañas sin desplazarse', lead: 'El estilo PES 6 Editar se rehízo con la referencia del menú original, y se ordenaron varias partes de la interfaz.', items: [
    ['interfaz', 'Estilo PES 6 Editar rehecho', 'Ahora se parece al menú Editar de PES 6: barra de título gris carbón, botones y listas como barras plateadas con bordes redondeados, la opción elegida en amarillo dorado y un fondo ámbar desenfocado con luces, estelas y líneas de puntos. Está hecho a mano, sin imágenes del juego.'],
    ['interfaz', 'Sonidos de PES 6', 'En el estilo PES 6 suenan los sonidos del menú: "confirmar" al tocar opciones, pestañas y acciones, y "deshacer" al volver, cerrar, apretar Esc o deshacer un cambio (Ctrl+Z).', ['En "🖥️ Gráficos", "Sonidos de menú" elige si suenan solo en PES 6, siempre o nunca.', 'Ajustá el volumen ahí mismo.']],
    ['interfaz', 'Pestañas sin desplazarse', 'La barra de Equipos, Selecciones, Jugadores, etc. es más ancha y usa letra un poco más chica, así entra completa sin tener que desplazarla. En pantallas más angostas se ocultan los avisos de estado para dejar lugar.'],
    ['interfaz', 'Apariencia según el estilo', 'Con los estilos Clásico, Retro o PES 6 Editar, los colores los pone el estilo: Apariencia solo deja cambiar el tamaño de la letra y la cantidad de efectos, y tiene un botón para volver al estilo Moderno.'],
    ['interfaz', 'Sin medidor de fluidez', 'Se sacó "Fluidez ahora" del panel de Gráficos.'],
    ['plantel', 'Capitán desde Acciones', 'La columna "Cap." se reemplazó: el capitán se elige en el menú de la columna Acciones de cada jugador, y se marca con una "C" al lado de su nombre.', ['En la tabla del plantel, abrí el menú de Acciones del jugador.', 'Elegí "© Hacer capitán".']],
    ['musica', 'Video de YouTube arriba del reproductor', 'Cuando suena un video de YouTube, se ve chiquito justo arriba del reproductor. Si abrís el panel grande, el video toma el lugar de la carátula.']] },
  { v: 12, d: '2026-10-13 03:30', t: 'Estilo PES 6 Editar y sonidos de menú', lead: 'Un modo gráfico nuevo inspirado en el modo Editar de PES 6, con sonidos al moverte por los menús.', items: [
    ['interfaz', 'Modo gráfico "PES 6 Editar"', 'Inspirado en el modo Editar de PES 6: fondo azul acero con brillos diagonales, barras y botones plateados, línea naranja arriba de cada panel, y la selección (pestaña, equipo o jugador elegido) resaltada con una barra naranja y dorada inclinada. Los títulos van en cursiva.', ['Tocá "🖥️ Gráficos".', 'En "Modo gráfico" elegí "PES 6 Editar".']],
    ['interfaz', 'Sonidos de menú', 'Pitidos cortos como los de los juegos de esa época: uno suave al pasar el mouse por pestañas, equipos y opciones, otro al tocar, uno de confirmación al guardar y otro para volver o cerrar (también con Esc). Se generan en la página, no son sonidos sacados del juego.', ['En "🖥️ Gráficos", "Sonidos de menú": "Solo en PES 6" (lo normal), "Siempre" o "Nunca".', 'Ajustá "Volumen de los sonidos" a tu gusto.']]] },
  { v: 11, d: '2026-10-13 03:05', t: 'Fuente nueva, gráficos y YouTube', lead: 'La página estrena fuente, se pueden elegir modos y calidad gráfica, y el reproductor suma carátulas automáticas y listas de YouTube.', items: [
    ['interfaz', 'Fuente QuickExpress en toda la página', 'La fuente de estilo PES pasó a ser la de toda la página. Se reparó (Chrome la rechazaba por un error interno del archivo), se le agregaron las letras que faltaban para el español y para nombres de jugadores (á, é, í, ó, ú, ñ, ü, ö, à, ã, ç, ¿, ¡, comillas, coma) y se angostó al 80 % para que entre bien en botones y pestañas. Se puede seguir cambiando.', ['Tocá "🎨 Apariencia".', 'En "Fuente de la página" elegí "QuickExpress (PES Editor)", "QuickExpress con estela en títulos" (la versión original, con la línea de velocidad en las minúsculas), "Saira (la anterior)", otra fuente de tu PC o "Cargar…" para usar un archivo.', 'Con Títulos, Texto y Números y datos elegís dónde se aplica.']],
    ['interfaz', 'Botón Gráficos', 'Al lado de Apariencia hay un botón 🖥️ Gráficos con el modo gráfico y la calidad. También muestra cuántos cuadros por segundo está dibujando la página y sugiere qué calidad usar.', ['Tocá "🖥️ Gráficos".', 'Elegí un modo: Moderno, Clásico o Retro.', 'Elegí la calidad: Baja, Media o Alta.']],
    ['interfaz', 'Modos Clásico y Retro', 'Clásico imita a los editores de escritorio de antes: grises, botones en relieve, sin brillos ni transparencias (tiene versión clara y oscura). Retro está inspirado en los menús de PES de PS2: azul profundo, amarillo, pestañas inclinadas y líneas de TV vieja. Los dos se combinan con la fuente elegida.'],
    ['velocidad', 'Calidad gráfica Baja, Media y Alta', 'Baja saca animaciones, desenfoques, sombras y efectos, simplifica la intro y dibuja el 3D a resolución normal: la página anda más liviana en PCs lentas. Media es lo de siempre. Alta sube todo al máximo: el 3D se dibuja con más resolución que la pantalla (supermuestreo), desenfoques y brillos más intensos y más chispas en la intro.'],
    ['interfaz', 'Guardar a la altura del logo', 'El botón "Guardar en el juego" quedó centrado con el logo, a la derecha de la barra de arriba.'],
    ['musica', 'Canciones con su carátula', 'Al agregar canciones, el editor lee las etiquetas del archivo (MP3, FLAC y M4A): título, artista, año y la carátula que traen adentro. Si una canción no tiene carátula, se arma una con colores propios, una nota musical y sus iniciales.'],
    ['musica', 'Arreglo del diseño del reproductor', 'Los nombres largos ya no desarman la lista y las canciones sin carátula ya no muestran una imagen rota.'],
    ['musica', 'Listas de YouTube', 'Se puede pegar el link de una lista o de un video de YouTube y se suman al reproductor con sus títulos y miniaturas. YouTube no permite ocultar sus videos ni sacarles el audio, así que se ven en una ventanita al lado del reproductor. Funcionan los controles, el volumen y los pases suaves entre temas (el Remix con filtros solo funciona con canciones propias). Hace falta internet y funciona en la versión web; abierto como archivo en la PC, YouTube suele bloquear la reproducción.', ['Abrí el reproductor y tocá "▶ YouTube".', 'Pegá el link (por ejemplo youtube.com/playlist?list=…) y tocá "Cargar".', 'Para quitar un video, tocá la ✕ al lado en la lista.']]] },
  { v: 10, d: '2026-10-13 02:40', t: 'Primera versión pública (alpha)', lead: 'PES Editor se publica en GitHub como versión alpha: se puede usar desde cualquier PC con Chrome o Edge, sin instalar nada.', items: [
    ['archivo', 'Disponible en internet', 'El editor se publica en GitHub Pages. Se abre desde el link, elige tu carpeta Documentos una vez y trabaja con tus archivos sin subirlos a ningún lado: todo se procesa en tu PC.'],
    ['interfaz', 'Se puede instalar como app', 'Desde Chrome o Edge se instala con su ícono en el escritorio y el menú Inicio, se abre en su propia ventana y funciona sin internet. Las actualizaciones llegan solas al abrirlo con conexión.', ['Abrí la página en Chrome o Edge.', 'Tocá el ícono de instalar en la barra de direcciones (o el menú ⋮ → "Instalar PES Editor").', 'Desde ahí se abre como cualquier programa.']],
    ['musica', 'Reproductor sin canciones incluidas', 'La versión pública no trae los temas de los menús de PES por derechos de autor. El reproductor funciona igual: cada uno agrega sus canciones y carátulas, que quedan guardadas en su navegador.', ['Tocá el reproductor abajo a la izquierda.', 'Tocá "＋ Agregar canciones" y elegí tus archivos de música.']],
    ['interfaz', 'Novedades con fecha y más detalle', 'Las versiones se numeran v0.0NN y cada una muestra fecha y hora. Cada cambio tiene explicación y, cuando hace falta, los pasos para usarlo. Hay buscador, filtros por tema y "Abrir todo / Cerrar todo".', ['Usá los botones de arriba para ver solo un tema (Kits, Plantel, Música…).', 'Escribí en el buscador para encontrar un cambio por palabra, por ejemplo "brillo" o "WEPES".']]] },
  { v: 9, d: '2026-10-13 02:07', t: 'Reproductor de música', lead: 'La música pasó a tener su propio reproductor fijo abajo a la izquierda, con cinco temas de menú de PES de la época de PS2.', items: [
    ['musica', 'Reproductor abajo a la izquierda', 'Muestra la carátula, el nombre del tema, el juego y el año. Tiene play/pausa, siguiente y una línea de progreso. Tocando la carátula o el título se abre el panel grande; con el botón − queda achicado a un círculo con la carátula, que gira mientras suena.', ['Tocá la carátula para abrir el panel.', 'Tocá − arriba del panel para dejarlo como círculo.', 'Tocá el círculo para volver a la barra.']],
    ['musica', 'Cinco temas de menú', 'PES 3 (Main Menu), PES 4 (Main Menu), PES 5 (Spiral), PES 6 (Existence) y PES 2008 (Go for the Goal). Se guardaron en formato Opus para que el archivo pese menos sin perder calidad notable.'],
    ['musica', 'Controles completos', 'En el panel grande: barra para adelantar o volver, anterior (si el tema ya avanzó más de 4 segundos, vuelve al principio), siguiente, aleatorio, repetir (toda la lista → solo este tema → sin repetir), volumen y silencio. El editor recuerda el volumen, el modo y el último tema que sonó.'],
    ['musica', 'Pase entre canciones: Corte, Suave o Remix', 'Corte pasa directo. Suave baja una canción mientras sube la otra, sin silencio en el medio. Remix funciona como un DJ: a la canción que termina se le cierra el sonido con un filtro y le queda un eco, y la nueva entra sin graves y se va abriendo. La duración del pase se ajusta entre 2 y 14 segundos (cuando tocás "siguiente" a mano, el pase dura como máximo 3,5 segundos).', ['Abrí el panel grande.', 'En "Pase entre canciones" elegí Corte, Suave o Remix.', 'Mové "Duración" para que el pase sea más corto o más largo.']],
    ['musica', 'Colores que se adaptan', 'El reproductor toma el color de la carátula de cada tema (botones, barra y brillo). En pantallas chicas se acomoda como una barra a lo ancho y el panel se abre hacia arriba. También responde a las teclas multimedia del teclado (play, siguiente, anterior).'],
    ['musica', 'Tus canciones y carátulas', 'Podés sumar canciones propias y cambiar la carátula de cualquier tema. Quedan guardadas en tu navegador (no se suben a ningún lado).', ['Abrí el panel y tocá "＋ Agregar canciones"; podés elegir varios archivos a la vez.', 'Para quitar una canción tuya, tocá la ✕ al lado en la lista.', 'Para cambiar una carátula, poné ese tema y tocá "🖼 Carátula". Tocándolo otra vez podés volver a la original.']],
    ['archivo', 'Versión web para GitHub Pages', 'Además del archivo único, hay una versión separada (index.html + carpeta music) pensada para publicarse en internet. Si la carpeta music no está, el reproductor funciona igual y cada uno agrega sus canciones.']] },
  { v: 8, d: '2026-10-13 00:07', t: 'Música, logo vectorial y fotos en el plantel', lead: 'Primera versión con música, el logo nítido a cualquier tamaño y las fotos de los jugadores en la tabla del plantel.', items: [
    ['musica', 'Música al abrir la página', 'Suena el tema del menú de PES 5. Los navegadores no dejan que una página suene sola hasta que hacés algo, así que si la bloquean empieza con tu primer clic o tecla (por ejemplo al tocar "Elegir mi carpeta Documentos").'],
    ['interfaz', 'Logo de la barra en vector (SVG)', 'El logo de arriba usa los archivos vectoriales: plateado en modo oscuro y negro en modo claro. Se ve nítido con cualquier zoom y al cambiar de modo pasa de uno al otro con un fundido.'],
    ['interfaz', 'Paso suave de la carga a la página', 'Cuando termina de cargar el EDIT, el fondo de la introducción se agranda y se desenfoca mientras se desvanece, la página aparece de a poco y el logo vuela hasta su lugar en la barra.'],
    ['plantel', 'Fotos en la tabla del plantel', 'Cada jugador muestra su foto (la misma minicara que usa la Formación) dentro de un círculo con los colores del equipo. Antes solo aparecían si la Formación estaba en modo Fotos y eran muy chicas. Si un jugador no tiene foto, queda la camiseta. Al pasar el mouse por la fila, la foto se agranda un poco.', ['Tocá "Conectar carpeta Sider" para que el editor encuentre las minicaras del juego.', 'Abrí un equipo: las fotos aparecen solas en la pestaña Plantel.']]] },
  { v: 7, d: '2026-10-12 23:50', t: 'Intro con neón y sección Novedades', lead: 'La pantalla de carga se volvió más llamativa y se agregó esta sección.', items: [
    ['interfaz', 'Intro con efectos', 'El logo entra con un zoom, un destello de luz, rayos que giran detrás, chispas que suben, un piso con grilla tipo estadio de noche y un reflejo debajo.'],
    ['interfaz', 'Brillo neón que se prende y se apaga', 'El contorno de las letras, las barras y las estrellas se iluminan como un tubo de neón: se enciende con parpadeos, queda prendido, se apaga despacio y vuelve a prenderse. Mientras carga el EDIT late más rápido y al terminar queda fijo. Usa el color de acento de la página (cambia con los colores del equipo). Si Windows tiene activado "reducir animaciones", se muestra fijo y sin efectos.'],
    ['interfaz', 'Pestaña Novedades', 'Al lado de Archivo. Cuando hay una versión que todavía no viste aparece un punto que titila en la pestaña; se apaga cuando entrás.'],
    ['kits', 'Botón "Conectar carpeta Sider"', 'El botón que antes decía "Conectar Parche" ahora se llama "Conectar carpeta Sider" y tiene el ícono del martillo y la llave. Hace lo mismo: elegís la carpeta de Sider del juego y el editor lee kits, caras, escudos y nombres de jugadores.']] },
  { v: 6, d: '2026-10-12 22:52', t: 'El EDIT se encuentra solo', lead: 'Ya no hace falta buscar el archivo a mano: el editor lo encuentra en tu carpeta Documentos.', items: [
    ['archivo', 'Búsqueda automática del EDIT', 'El editor busca KONAMI\\eFootball PES 2021 SEASON UPDATE dentro de Documentos (aunque esté en otra subcarpeta) y abre el EDIT00000000 más reciente. Si hay dos con la misma fecha, prefiere el de la carpeta drmp antes que el de la carpeta save.', ['La primera vez tocá "📂 Elegir mi carpeta Documentos". La ventana ya se abre en Documentos: solo tocá "Seleccionar carpeta".', 'En el aviso del navegador elegí "Permitir en cada visita" para que la próxima vez entre directo.']],
    ['archivo', 'Cambiar entre EDITs', 'En la pestaña Archivo, la tarjeta "Carpeta del juego" lista todos los EDIT encontrados (drmp, save u otras cuentas de Steam) con fecha y tamaño. "Abrir este" cambia al otro; si tenés cambios sin guardar, primero te pregunta.'],
    ['interfaz', 'Pantalla de carga', 'Mientras busca y lee el EDIT se muestra el logo con los pasos: buscando la carpeta, encontrada, leyendo el archivo (con el tamaño), armando equipos y jugadores, listo.'],
    ['archivo', 'Pestaña WEPES', 'Muestra los archivos de la carpeta WEPES del juego con miniaturas (png, jpg, dds y ftex). Podés entrar a subcarpetas, ver cada imagen en grande con sus medidas, descargarla y copiar archivos nuevos adentro. Si la carpeta no existe, aparece un botón para crearla.', ['Abrí la pestaña WEPES.', 'Tocá "Agregar archivos…" para copiar imágenes o texturas adentro.', 'Tocá un archivo para verlo en grande.']],
    ['archivo', 'Botones quitados', 'Se sacaron "Abrir carpeta" y "Abrir archivo" de la barra. Si el navegador no permite leer carpetas (Firefox o Safari), la pantalla de carga ofrece elegir el EDIT a mano.']] },
  { v: 5, d: '2026-10-12 22:26', t: 'Logo, cabecera nueva y fuente propia', lead: 'El editor estrena logo, se ordenó la barra de arriba y se puede usar cualquier fuente para toda la página.', items: [
    ['interfaz', 'Logo PES Editor', 'El logo de PES Editor reemplaza el título de texto "Editor EDIT 21" en la parte de arriba.'],
    ['interfaz', 'Logo para modo claro y oscuro', 'Cada modo tiene su versión del logo, sin transparencia ni bordes redondeados, pintada sobre el color real de la barra.'],
    ['interfaz', 'El logo vuelve al inicio', 'Tocar el logo te lleva a la lista de equipos y sube al principio de la página.'],
    ['interfaz', 'Fuente propia para toda la página', 'Podés elegir una fuente instalada en tu PC o cargar un archivo de fuente, y decidir si se aplica a títulos, texto y/o números. La fuente cargada queda guardada en el navegador.', ['Tocá "🎨 Apariencia".', 'En "Fuente de la página" elegí una de la lista o tocá "Cargar…" y elegí un archivo .ttf, .otf, .woff o .woff2.', 'Con los botones Títulos, Texto y Números y datos elegís dónde se usa. Abajo ves una vista previa.']],
    ['interfaz', 'Barra de arriba ordenada', 'El buscador quedó al lado del logo, con "Editor EDIT 21 · eFootball PES 2021" a su derecha; los botones quedaron debajo y "Guardar en el juego" a la derecha.']] },
  { v: 4, d: '2026-10-12 22:11', t: 'Brillo, cámara, tela y fondo HDRI', lead: 'El estudio de kits se acercó a cómo se ve la camiseta en el juego.', items: [
    ['kits', 'Brillo desde el alfa de la textura', 'En la textura del kit (por ejemplo u0100p1), el canal alfa marca cuánto brilla cada parte: blanco brilla más, negro menos. El visor 3D lo aplica como el juego y se puede ver y modificar.', ['En Estudio de kits abrí la vista del brillo.', 'Ajustá nivel y contraste, o invertilo.', 'Pintá con el pincel sobre las zonas que querés más o menos brillantes; "Deshacer" vuelve atrás.', 'Al guardar se reconstruye el alfa en la resolución original y se hace una copia de respaldo del archivo anterior.']],
    ['kits', 'Cambios con animación y más control de cámara', 'Al cambiar opciones de la vista, el 3D se refresca con una transición. Hay vistas fijas (frente, espalda, costados, tres cuartos, arriba, cerca), se puede acercar, mover la cámara y usar el teclado.'],
    ['kits', 'Uniones del modelo arregladas', 'Las partes del modelo (cuerpo, mangas, cuello y short) comparten las normales en los bordes, así no se ven cortes ni cambios de luz en las uniones.'],
    ['kits', 'Tela y relieve (normal map)', 'Se puede elegir un tipo de tela (lisa, malla, piqué, panal, acanalada, sarga, jacquard o algodón retro) y el relieve de los dibujos del kit. El editor genera el normal map que el juego aplica sobre la camiseta. El escudo con relieve depende de que el juego lo cargue.'],
    ['kits', 'Elegir cuello y short', 'Los selectores muestran cada modelo en una vista previa que gira; "Usar este cuello" cambia el config.txt del kit.'],
    ['kits', 'Luz y fondo HDRI', 'Los controles de luz se rediseñaron, hay una esfera para mover la dirección del sol y se puede cargar un fondo HDRI propio que también ilumina la camiseta.']] },
  { v: 3, d: '2026-10-12 21:28', t: 'Estudio de kits estilo PES Master', lead: 'Se armó un estudio para ver y editar los kits del kit-server del juego.', items: [
    ['kits', 'Visor 3D con los modelos reales', 'La camiseta, las mangas, más de 100 cuellos, los 16 shorts y las medias salen del CometKIT previewer, con iluminación tipo estadio.'],
    ['kits', 'Editar el config.txt sin escribir', 'Los valores del config del kit (cuello, short, colores y demás) se cambian con controles y el 3D se actualiza al instante.'],
    ['kits', 'Subir texturas al kit-server', 'Podés cargar la textura del kit, el normal map y las fuentes (nombre, número de espalda, de pecho y de short). El editor las convierte al formato del juego (FTEX) y guarda una copia del archivo anterior.', ['Conectá la carpeta Sider.', 'Abrí el equipo y entrá a "Estudio de kits".', 'En cada casillero de textura tocá cargar y elegí una imagen.']],
    ['kits', 'Generador de fuentes', 'Arma la textura de letras o números con la fuente, los colores, los bordes y la sombra que elijas, respetando las casillas de las plantillas del juego.']] },
  { v: 2, d: '2026-10-12 20:51', t: 'Más rápido y visor 3D', lead: 'Optimización general sin quitar animaciones.', items: [
    ['velocidad', 'Abrir equipos es casi instantáneo', 'Abrir un equipo pasó de unos 3 segundos a 0,3. Las listas largas dibujan solo lo que está en pantalla y los menús de cada fila se completan recién cuando los abrís.'],
    ['kits', 'Maqueta del kit y visor 3D', 'La maqueta plana del kit se corrigió y se sumó el visor 3D.'],
    ['interfaz', 'Ayudas más claras', 'Cada sección tiene un recuadro de ayuda que se abre y se cierra, con explicaciones más largas. El editor recuerda cuáles dejaste abiertos.']] },
  { v: 1, d: '2026-10-12 19:11', t: 'Plantel como tabla, Apariencia y valoración animada', lead: 'El plantel se convirtió en una tabla de datos, se puede personalizar el aspecto del editor y los cambios de valoración se ven mejor.', items: [
    ['plantel', 'Valoración nueva revelada', 'Al aplicar cambios de valoración, la nueva cifra aparece con una animación de revelado en lugar de flechas +N, así se ve directamente cómo quedó cada jugador.'],
    ['plantel', 'Tabla del plantel', 'Se ordena tocando el título de cada columna, se filtra por texto, por posición (ARQ, DEF, MED, DEL) y por situación (titulares, banco, reserva, sin proteger). Hay tres densidades de filas, elección de columnas y exportación.', ['Tocá el título de una columna para ordenar; tocalo otra vez para invertir.', 'Marcá varias filas con la casilla para aplicar una acción a todas juntas.', '"Columnas" muestra u oculta datos; "Exportar" descarga la lista.']],
    ['interfaz', 'Panel de Apariencia', 'Mezcla la paleta del editor con los colores del equipo que abrís: modo claro u oscuro, paleta base, qué color del equipo manda, cuánto se mezcla, fondos teñidos, esquinas y tamaño de letra.', ['Tocá "🎨 Apariencia".', 'Mové "Mezcla con el equipo" para que el editor tome los colores del club.', '"Volver a lo original" deshace todo.']]] },
];
const NEWS_VER = NEWS[0].v;
const newsSeen = () => { try { return +localStorage.getItem('pes-editor-news-seen') || NEWS_VER - 1; } catch { return NEWS_VER - 1; } };
function newsBadge() { const c = $('cNews'); if (!c) return; const n = NEWS.filter(x => x.v > newsSeen()).length; c.textContent = n ? '●' : ''; c.classList.toggle('newsdot', !!n); }
const NEWS_MES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
function newsDate(d) {
  const [ymd, hm] = d.split(' '), [y, m, dd] = ymd.split('-').map(Number), t = new Date(`${ymd}T${hm}:00-03:00`), mins = Math.round((Date.now() - t) / 60000);
  const ago = mins < 1 ? 'recién' : mins < 60 ? `hace ${mins} min` : mins < 1440 ? `hace ${Math.round(mins / 60)} h` : `hace ${Math.round(mins / 1440)} días`;
  return { full: `${dd} ${NEWS_MES[m - 1]} ${y} · ${hm}`, ago, iso: t.toISOString() };
}
let NEWS_F = 'todo', NEWS_Q = '', NEWS_OPEN = null;
function renderNews(m) {
  const seen = newsSeen(), q = NEWS_Q.trim().toLowerCase();
  const hit = it => !q || it.slice(1).flat().join(' ').toLowerCase().includes(q);
  const list = NEWS.map(r => ({ ...r, items: r.items.filter(it => (NEWS_F === 'todo' || it[0] === NEWS_F) && hit(it)) })).filter(r => r.items.length || (q && r.t.toLowerCase().includes(q)));
  const isOpen = (r, i) => NEWS_OPEN ? NEWS_OPEN.has(r.v) : (q || NEWS_F !== 'todo') ? true : i < 2;
  m.innerHTML = `<section class="card newsc">
    <div class="newshead"><div><h2>Novedades</h2><p class="note">Lo que cambió en cada versión de PES Editor Rebuilt, con fecha y cómo usarlo. Estás usando la <b>${newsVer(NEWS_VER)} alpha</b> del ${newsDate(NEWS[0].d).full}.</p></div>
      <div class="newstools"><input type="search" id="newsQ" placeholder="Buscar en los cambios…" value="${esc(NEWS_Q)}" aria-label="Buscar en las novedades"><button type="button" class="btn small ghost" id="newsAll">${NEWS_OPEN && NEWS_OPEN.size === NEWS.length ? 'Cerrar todo' : 'Abrir todo'}</button></div></div>
    ${typeof devCard === 'function' ? devCard() : ''}
    <div class="seg newsf">${[['todo', 'Todo'], ...Object.entries(NEWS_TAGS)].map(([k, n]) => `<button type="button" aria-pressed="${NEWS_F === k}" data-nf="${k}">${n}</button>`).join('')}</div>
    ${list.length ? '' : '<p class="note" style="margin-top:14px">No hay cambios que coincidan con la búsqueda.</p>'}
    <ol class="newslist">${list.map((r, i) => { const dt = newsDate(r.d); return `<li class="newsv ${r.v > seen ? 'fresh' : ''}" style="--i:${i}">
      <div class="newsbadge"><b>${newsVer(r.v)}</b>${r.v === NEWS_VER ? '<span class="chip ok">Actual</span>' : ''}${r.v > seen ? '<span class="chip newchip">Nuevo</span>' : ''}</div>
      <details class="newsbody" data-v="${r.v}" ${isOpen(r, i) ? 'open' : ''}><summary><span class="newstt"><h3>${esc(r.t)}</h3><time datetime="${dt.iso}" title="${dt.ago}">📅 ${dt.full} <small>· ${dt.ago}</small></time></span><span class="newsn">${r.items.length} ${r.items.length === 1 ? 'cambio' : 'cambios'}</span></summary>
        ${r.lead ? `<p class="newslead">${esc(r.lead)}</p>` : ''}
        <ul>${r.items.map(([k, h, txt, steps]) => `<li><span class="newstag" data-k="${k}">${NEWS_TAGS[k]}</span><div><b class="newsh">${esc(h)}</b><p>${esc(txt)}</p>${steps ? `<div class="newshow"><span>Cómo usarlo</span><ol>${steps.map(s => `<li>${esc(s)}</li>`).join('')}</ol></div>` : ''}</div></li>`).join('')}</ul></details></li>`; }).join('')}</ol>
  </section>`;
  m.querySelectorAll('[data-nf]').forEach(b => b.onclick = () => { NEWS_F = b.dataset.nf; NEWS_OPEN = null; renderNews(m); });
  const qi = m.querySelector('#newsQ'); qi.oninput = () => { NEWS_Q = qi.value; NEWS_OPEN = null; const p = qi.selectionStart; renderNews(m); const n = m.querySelector('#newsQ'); n.focus(); n.setSelectionRange(p, p); };
  m.querySelector('#newsAll').onclick = () => { const all = !(NEWS_OPEN && NEWS_OPEN.size === NEWS.length); NEWS_OPEN = new Set(all ? NEWS.map(r => r.v) : []); renderNews(m); };
  m.querySelectorAll('details.newsbody').forEach(d => d.addEventListener('toggle', () => { if (!NEWS_OPEN) NEWS_OPEN = new Set([...m.querySelectorAll('details.newsbody[open]')].map(x => +x.dataset.v)); else d.open ? NEWS_OPEN.add(+d.dataset.v) : NEWS_OPEN.delete(+d.dataset.v); const b = m.querySelector('#newsAll'); if (b) b.textContent = NEWS_OPEN.size === NEWS.length ? 'Cerrar todo' : 'Abrir todo'; }));
  try { localStorage.setItem('pes-editor-news-seen', NEWS_VER); } catch { }
  newsBadge();
}
